window.MD102_V6_LABS=[{"id":"I01","objectives":["INF-001","INF-002","INF-003"],"title":"Device identity: registered versus joined","scenario":"Northstar issues a corporate Windows laptop to a new accountant and allows a contractor to use personal iPad Outlook. You must choose different identity and management relationships.","mental":"Think of Entra identity as the employee badge; MDM enrollment is the separate permission to manage the device. Registration is not the same as a corporate join or MDM enrollment.","why":"Choosing the wrong relationship can either leave a corporate PC unmanaged or expose personal devices to unnecessarily broad controls.","prerequisites":"Confirm ownership, OS, licensing, organization policy, and whether the device needs full MDM management or only protected-app access.","verify":"Corporate Windows appears as Entra joined AND has a separate Intune MDM record; contractor app access can be governed by app protection without automatically managing the entire iPad.","failure":"The Windows machine appears in Entra but not Intune after sign-in.","recovery":"Inspect MDM user scope, license assignment, enrollment restrictions, Windows edition, and network connectivity before wiping the laptop.","risk":"Never assume that registration proves encryption compliance or grants permission to wipe a personal device.","settings":[{"prompt":"Corporate Windows identity","choices":[{"text":"Microsoft Entra join","why":"Provides an organization-owned identity relationship suitable for cloud-managed Windows endpoints."},{"text":"Microsoft Entra registration only","why":"Registration identifies a personal device but does not establish corporate-joined Windows behavior."},{"text":"No identity registration","why":"Without an identity relationship you cannot target the expected cloud controls."}],"answer":0},{"prompt":"Management method","choices":[{"text":"Intune MDM enrollment with eligible license","why":"Entra join and Intune MDM enrollment are related but distinct; verify both records."},{"text":"Treat join as automatic proof of management","why":"A joined device may still fail MDM enrollment due to licensing or policy scope."},{"text":"Only Microsoft 365 app sign-in","why":"App sign-in does not automatically establish full device management."}],"answer":0},{"prompt":"Verification evidence","choices":[{"text":"Check Entra device record AND Intune managed-device record","why":"Both relationships must be independently verified before saying the corporate endpoint is managed."},{"text":"Check only that user can open Outlook","why":"Outlook can function without Intune device enrollment."},{"text":"Check only the device name","why":"Names are not evidence of management or compliance."}],"answer":0}],"incident":{"prompt":"Which missing fact most directly explains the failure?","choices":[{"text":"MDM auto-enrollment scope or license is missing","why":"A successful Entra join does not bypass the separate Intune enrollment prerequisites."},{"text":"The device hostname starts with W11","why":"The hostname is not a sufficient reason for missing MDM enrollment."},{"text":"The user did not install Teams","why":"Teams installation is not an Intune enrollment prerequisite."}],"answer":0},"concept":{"prompt":"Why should BYOD be treated differently?","choices":[{"text":"Apply the least invasive protection that meets data risk","why":"App protection can protect organizational app data without broad control of an employee-owned device."},{"text":"All personal phones should be wiped at enrollment","why":"Wiping personal property is disproportionate and not a normal default."},{"text":"Personal devices never need access controls","why":"Corporate data still requires authentication and suitable protection."}],"answer":0},"domain":"infrastructure","doc":"https://learn.microsoft.com/en-us/search/?terms=Device%20identity%3A%20registered%20versus%20joined%20Microsoft%20Intune"},{"id":"I02","objectives":["INF-004","INF-011","INF-012","INF-013"],"title":"Dynamic groups, roles and safe assignments","scenario":"A security engineer wants encryption on Northstar Accounting Windows laptops but not employees’ personal phones. A helpdesk technician must see only the devices they support.","mental":"A group determines WHO receives a policy; a role determines WHAT an admin may do; a scope tag affects WHICH objects the admin can see/manage. They are separate controls.","why":"Confusing group assignment with RBAC can make policies overbroad or expose administration beyond support duties.","prerequisites":"Use an owner/platform-aware pilot group, least privilege RBAC, and confirm the group membership preview before a broad assignment.","verify":"The pilot consists only of corporate Windows Accounting endpoints; a helpdesk role cannot wipe unrelated devices; exclusions are documented.","failure":"A personally owned Android device unexpectedly matches the security policy.","recovery":"Inspect actual group membership, device ownership attributes, dynamic rule, and policy filters; do not assume a scope tag changes policy deployment.","risk":"Broad All users targeting and untested dynamic rules can affect unsupported platforms or personal devices.","settings":[{"prompt":"Policy targeting","choices":[{"text":"Dynamic group for corporate Accounting Windows devices","why":"Membership based on relevant device attributes is more precise than targeting everyone."},{"text":"All devices without filters","why":"Overly broad assignment includes other departments and platforms."},{"text":"Role scope tags instead of assignments","why":"Scope tags do not replace policy assignment targeting."}],"answer":0},{"prompt":"Helpdesk permissions","choices":[{"text":"Limited Intune RBAC role plus appropriate scope tags","why":"Permissions and visibility should be separately configured and tested."},{"text":"Global Administrator for every technician","why":"Global Administrator grants unnecessary tenant-wide privileges."},{"text":"No role, only an assignment group","why":"Device assignment groups do not confer administrator permissions."}],"answer":0},{"prompt":"Pilot validation","choices":[{"text":"Review members and test one eligible and one excluded endpoint","why":"Positive and negative tests catch an overbroad rule before rollout."},{"text":"Deploy first and review complaints","why":"Reactive rollout risks impact outside pilot."},{"text":"Count only total group size","why":"A count does not reveal inappropriate members."}],"answer":0}],"incident":{"prompt":"What explains the Android receiving the policy?","choices":[{"text":"An overly broad dynamic membership rule","why":"Membership and assignment are the first investigation points for targeting surprises."},{"text":"Intune ignores all device groups","why":"Intune supports group-based targeting; this would not be the default explanation."},{"text":"The scope tag allowed Android enrollment","why":"A scope tag controls admin scoping, not whether a device matches a policy assignment."}],"answer":0},"concept":{"prompt":"What is the difference between group and scope tag?","choices":[{"text":"Groups target recipients; scope tags restrict admin visibility","why":"They serve different layers of endpoint management."},{"text":"Both grant user sign-in rights","why":"Neither is a substitute for Entra identity authentication."},{"text":"Scope tags deploy app packages","why":"App assignments determine target population."}],"answer":0},"domain":"infrastructure","doc":"https://learn.microsoft.com/en-us/search/?terms=Dynamic%20groups%2C%20roles%20and%20safe%20assignments%20Microsoft%20Intune"},{"id":"I03","objectives":["INF-005","INF-006"],"title":"Windows automatic enrollment readiness","scenario":"A new hire signs in to a company Windows 11 laptop. It is Entra joined, but it never appears under Intune Devices.","mental":"Enrollment is a sequence: user licensed → MDM authority and scope configured → OS eligible → joined/signed-in → service enrolls device → device reports check-in.","why":"An enrollment failure upstream prevents all downstream configuration, apps, compliance, and remote operations.","prerequisites":"Confirm Intune license, automatic MDM enrollment user scope, supported Windows edition, network reachability, and enrollment restrictions.","verify":"Entra and Intune both show the device. It reports a recent check-in and platform-specific policy result.","failure":"Intune has no managed record even though Entra identity is healthy.","recovery":"Inspect tenant MDM user scope, licensing, enrollment restrictions, Windows event logs and Company Portal/MDM diagnostics in that order.","risk":"Do not wipe or factory reset before confirming whether the configuration prerequisites were ever satisfied.","settings":[{"prompt":"First admin control to inspect","choices":[{"text":"MDM user scope and assigned Intune license","why":"Automatic enrollment depends on eligibility and an appropriately scoped enrollment policy."},{"text":"Create a BitLocker policy first","why":"Encryption cannot resolve the missing management relationship."},{"text":"Rename the computer","why":"A hostname change does not repair the enrollment channel."}],"answer":0},{"prompt":"Pilot setup","choices":[{"text":"One test user and one supported Windows device","why":"A narrow pilot isolates root cause and keeps other users unaffected."},{"text":"All users and all devices immediately","why":"Large rollout obscures failures and increases operational risk."},{"text":"Use only a mobile device for Windows troubleshooting","why":"Platform-specific enrollment requirements differ."}],"answer":0},{"prompt":"Completion evidence","choices":[{"text":"Managed device ID and successful Intune check-in","why":"A real MDM record and recent check-in demonstrate enrollment progress."},{"text":"Device can reach a website","why":"Internet access alone is insufficient for MDM."},{"text":"User has an Entra account","why":"An identity account does not prove device enrollment."}],"answer":0}],"incident":{"prompt":"Which is a plausible root cause after Entra join succeeds?","choices":[{"text":"User outside MDM auto-enrollment scope","why":"Entra join and Intune automatic enrollment are separate configuration stages."},{"text":"Missing Microsoft Word shortcut","why":"Word is unrelated to MDM enrollment."},{"text":"Printer has no paper","why":"A printer cannot block the MDM user scope."}],"answer":0},"concept":{"prompt":"What should a technician verify before resetting a device?","choices":[{"text":"Enrollment prerequisites and MDM diagnostic logs","why":"Check configuration and evidence before a destructive action."},{"text":"Reset all pilot laptops at once","why":"That destroys useful evidence and affects other users."},{"text":"Delete Entra device record immediately","why":"Deleting device identity can complicate investigation."}],"answer":0},"domain":"infrastructure","doc":"https://learn.microsoft.com/en-us/search/?terms=Windows%20automatic%20enrollment%20readiness%20Microsoft%20Intune"},{"id":"I04","objectives":["INF-007","INF-009"],"title":"Apple enrollment: personal versus corporate","scenario":"Northstar has 20 company-owned iPads purchased through a reseller and one executive’s personal iPhone. The company requires standardized setup for corporate devices but only protected email on BYOD.","mental":"Automated Device Enrollment (ADE) depends on Apple Business Manager and Intune token/profile setup; personal iOS app protection is a different and often less invasive path.","why":"Enrollment ownership determines what Intune can supervise and which controls are appropriate. Do not equate app protection with full device management.","prerequisites":"Use a valid Apple MDM push certificate, appropriate ABM connection/ADE token for corporate inventory, an enrollment profile, and eligible device assignment.","verify":"Corporate iPads appear as supervised enrolled devices with the intended profile; personal iPhone data protection does not require unwanted full-device control.","failure":"Corporate iPad boots normally but skips the Remote Management setup screen.","recovery":"Check Apple Business Manager assignment to the correct MDM server, enrollment token synchronization, profile assignment and device eligibility.","risk":"Never import or deploy a corporate ADE profile to an unrelated personal phone.","settings":[{"prompt":"Corporate iPad enrollment","choices":[{"text":"Apple Business Manager with Automated Device Enrollment","why":"ADE supports centrally managed company-owned devices through Apple/Intune integration."},{"text":"Ask every employee to enroll via personal Apple ID","why":"A personal Apple ID is not a replacement for managed corporate enrollment."},{"text":"Use Windows Autopilot","why":"Autopilot is Windows provisioning, not Apple enrollment."}],"answer":0},{"prompt":"Personal iPhone access","choices":[{"text":"Use appropriate app protection and CA as required","why":"MAM policies can govern organization-app data without broad personal phone management."},{"text":"Force wipe of the entire personal phone","why":"Disproportionate and risks personal content."},{"text":"Do not protect organizational data","why":"Unmanaged access still needs controls."}],"answer":0},{"prompt":"Proof corporate iPad is enrolled","choices":[{"text":"Confirm ABM assignment, enrollment profile and Intune check-in","why":"The chain spans Apple Business Manager, Intune token/profile and device check-in."},{"text":"Only confirm the serial number exists in an invoice","why":"Purchasing evidence does not prove management."},{"text":"Only check that Wi-Fi works","why":"Wi-Fi is a prerequisite, not proof of ADE."}],"answer":0}],"incident":{"prompt":"Why is Remote Management missing during setup?","choices":[{"text":"Device not correctly assigned/synced with an ADE enrollment profile","why":"Without correct ABM/MDM association the device may follow ordinary setup."},{"text":"iPad screen brightness is too low","why":"Brightness is not the relevant identity/enrollment cause."},{"text":"Microsoft Teams needs an update","why":"Teams is independent of ADE setup."}],"answer":0},"concept":{"prompt":"What changes between company iPad and personal iPhone?","choices":[{"text":"Ownership, enrollment method and allowable management scope","why":"Choose management controls consistent with ownership and privacy."},{"text":"Both require Windows Autopilot","why":"Apple hardware does not use that Windows workflow."},{"text":"All Apple devices must be supervised","why":"Supervision and management availability depend on enrollment path."}],"answer":0},"domain":"infrastructure","doc":"https://learn.microsoft.com/en-us/search/?terms=Apple%20enrollment%3A%20personal%20versus%20corporate%20Microsoft%20Intune"},{"id":"I05","objectives":["INF-008","INF-010"],"title":"Android Enterprise enrollment choices","scenario":"Northstar needs rugged, single-purpose barcode scanners, fully managed corporate phones, and work profiles on employees’ personal Android devices.","mental":"Android Enterprise offers different ownership and deployment modes: dedicated devices are for single-purpose/shared scenarios, fully managed for corporate-only phones, and work profile separates work data.","why":"The mode determines app distribution, data separation, supported restrictions, and what a device wipe can affect.","prerequisites":"Connect Managed Google Play, configure compatible enrollment tokens, and check OEM/Android version plus provisioning options (such as zero-touch or Knox where applicable).","verify":"Dedicated scanners run kiosk apps; corporate phones are fully managed; BYOD work stays in the managed work profile.","failure":"A corporate scanner enrolls but still allows unrestricted personal apps.","recovery":"Inspect chosen ownership mode, kiosk settings, dedicated-device enrollment profile and app assignment.","risk":"Never use a personal work-profile enrollment as if it offered dedicated-device kiosk controls.","settings":[{"prompt":"Single-purpose scanners","choices":[{"text":"Corporate-owned dedicated-device enrollment","why":"Designed for kiosk, shared and task-specific devices."},{"text":"Personally owned work profile","why":"Supports personal/work separation, not a corporate kiosk use case."},{"text":"Microsoft Entra join Windows flow","why":"Android uses different enrollment technology."}],"answer":0},{"prompt":"Personal Android device","choices":[{"text":"Personally owned work profile","why":"Separates work apps/data from the personal space."},{"text":"Fully managed corporate-only","why":"Full device management is not the usual BYOD expectation."},{"text":"No enrollment or app controls","why":"Work information still requires suitable protection."}],"answer":0},{"prompt":"Managed app delivery","choices":[{"text":"Managed Google Play assignment to appropriate group","why":"Android Enterprise app management relies on managed app availability and assignment."},{"text":"Apple Volume Purchase Program","why":"Apple's app distribution is for Apple devices."},{"text":"Install every APK by email attachment","why":"Uncontrolled sideloading is not a responsible enterprise default."}],"answer":0}],"incident":{"prompt":"Why does the scanner show ordinary apps?","choices":[{"text":"The wrong ownership/profile or kiosk configuration was assigned","why":"Enrollment mode and kiosk restrictions determine this behavior."},{"text":"Android cannot support kiosk configurations","why":"Dedicated-device modes support kiosks where supported."},{"text":"Windows Autopatch is delayed","why":"Autopatch does not govern Android kiosk access."}],"answer":0},"concept":{"prompt":"Why do enrollment modes matter?","choices":[{"text":"They determine supported controls and personal/work boundaries","why":"The same policy cannot simply be assumed to work across modes."},{"text":"Only the icon theme changes","why":"Enrollment modes change management capabilities."},{"text":"They are interchangeable after syncing","why":"Capabilities depend on the management method."}],"answer":0},"domain":"infrastructure","doc":"https://learn.microsoft.com/en-us/search/?terms=Android%20Enterprise%20enrollment%20choices%20Microsoft%20Intune"},{"id":"I06","objectives":["INF-014","INF-015","SEC-047"],"title":"Compliance, BitLocker and Conditional Access","scenario":"A company Windows laptop is enrolled, but Microsoft 365 access is denied because the device is not encrypted. You need to remediate the actual security setting and evaluate access safely.","mental":"Configuration/security policies attempt to SET a device state. Compliance policies TEST that state. Conditional Access USES compliance as a sign-in grant signal. These are three different services.","why":"If you only create a compliance requirement, BitLocker does not magically turn on. If you enforce CA before a pilot, you can lock out healthy users.","prerequisites":"Confirm Windows edition and TPM/recovery escrow readiness; use a pilot group; validate compliant device reporting; use CA report-only where applicable.","verify":"Disk encryption succeeds, recovery key is escrowed, compliance re-evaluates successfully, and CA permits the intended sign-in after a fresh evaluation.","failure":"Device reports noncompliant while encryption policy is shown as assigned.","recovery":"Inspect BitLocker encryption state and encryption policy result, key escrow, last Intune check-in, compliance details, and Entra sign-in logs.","risk":"Never equate assigned policy with successfully applied encryption; preserve emergency access during CA rollout.","settings":[{"prompt":"Remediate missing encryption","choices":[{"text":"Deploy a Windows disk-encryption policy","why":"A security configuration changes device settings; compliance only evaluates their state."},{"text":"Create a second compliance rule only","why":"More rules do not encrypt the disk."},{"text":"Disable Conditional Access for the whole tenant","why":"That weakens access protection and hides the root cause."}],"answer":0},{"prompt":"Policy rollout","choices":[{"text":"Assign a tested pilot group and escrow recovery keys","why":"Encryption and recovery require a safe pilot and a usable key recovery process."},{"text":"Target every platform using the same Windows policy","why":"Encryption implementation and support differ across platforms."},{"text":"Skip recovery-key preparation","why":"Key recovery is critical in failure cases."}],"answer":0},{"prompt":"Access validation","choices":[{"text":"Check encryption, compliance report and Entra sign-in logs","why":"Three distinct signals establish remediation and access outcome."},{"text":"Check only that the policy was created","why":"Creation does not demonstrate device encryption or access."},{"text":"Check only that Outlook opens on another PC","why":"An unrelated device cannot validate this laptop."}],"answer":0}],"incident":{"prompt":"Policy assigned but device still noncompliant; what first?","choices":[{"text":"Examine per-setting encryption/compliance evaluation and last check-in","why":"Assigned does not mean successfully applied or recently evaluated."},{"text":"Duplicate the compliance policy without inspecting errors","why":"Duplication adds uncertainty without diagnosing the failure."},{"text":"Delete all Intune devices","why":"Destructive action without evidence is unsafe."}],"answer":0},"concept":{"prompt":"Why does CA depend on compliance freshness?","choices":[{"text":"Sign-in decisions need evaluated device posture, not admin intent","why":"CA consumes compliance signals rather than a mere policy name."},{"text":"CA encrypts disks itself","why":"It cannot replace a Windows disk-encryption policy."},{"text":"Policies always apply instantly","why":"Check-in and evaluation introduce delays."}],"answer":0},"domain":"infrastructure","doc":"https://learn.microsoft.com/en-us/search/?terms=Compliance%2C%20BitLocker%20and%20Conditional%20Access%20Microsoft%20Intune"},{"id":"I07","objectives":["INF-016","INF-017","INF-018","MAN-043"],"title":"Windows Hello, LAPS and local administration","scenario":"Northstar needs passwordless employee sign-in and unique recoverable local admin credentials for support technicians.","mental":"Windows Hello for Business binds secure sign-in to the user and device; Windows LAPS manages local admin passwords. Neither is a substitute for the other.","why":"Passwordless user authentication and local admin recovery have different threat models and recovery procedures.","prerequisites":"Validate supported identity join, device prerequisites, recovery backup directory and least-privilege admin rights before rollout.","verify":"Employees enroll Windows Hello credentials; local admin password backup/rotation succeeds; authorized staff retrieve only needed credentials.","failure":"A local administrator password is identical on many laptops despite LAPS policy assignment.","recovery":"Inspect LAPS policy settings, device state/OS support, backup directory, password management event logs and check-in.","risk":"Do not give every technician permanent global or local admin privileges to simplify support.","settings":[{"prompt":"Employee sign-in protection","choices":[{"text":"Windows Hello for Business policy","why":"Supports modern strong device-bound user authentication."},{"text":"Use one shared local administrator password","why":"Shared credentials amplify lateral movement risk."},{"text":"Grant global administrator to employees","why":"Global privileges are unrelated to daily sign-in."}],"answer":0},{"prompt":"Local administrator recovery","choices":[{"text":"Windows LAPS with supported password backup","why":"Unique rotating credentials reduce reuse and improve recovery."},{"text":"Write one static admin password in a spreadsheet","why":"A static shared secret is inappropriate endpoint management."},{"text":"Use a compliance policy to set the admin password","why":"Compliance can evaluate, but does not rotate local credentials."}],"answer":0},{"prompt":"Verification","choices":[{"text":"Check LAPS backup/rotation plus Hello provisioning status","why":"Both independent capabilities need validated evidence."},{"text":"Check only successful Teams sign-in","why":"Teams success says little about either control."},{"text":"Check only the user profile name","why":"Profile display name cannot prove security configuration."}],"answer":0}],"incident":{"prompt":"What explains identical local admin passwords?","choices":[{"text":"LAPS backup/rotation or assignment never became effective","why":"Inspect local LAPS policy and event evidence before rotation troubleshooting."},{"text":"Windows Hello PIN is too short","why":"WHfB and local admin LAPS are separate services."},{"text":"The default browser is Edge","why":"Browser choice does not determine LAPS rotation."}],"answer":0},"concept":{"prompt":"What is the distinct purpose of LAPS?","choices":[{"text":"Rotate and escrow local administrator credentials","why":"Prevents widely shared local admin passwords on managed machines."},{"text":"Protect Word documents with app PIN","why":"That is application data protection."},{"text":"Register personal Android devices","why":"That is mobile enrollment."}],"answer":0},"domain":"infrastructure","doc":"https://learn.microsoft.com/en-us/search/?terms=Windows%20Hello%2C%20LAPS%20and%20local%20administration%20Microsoft%20Intune"},{"id":"M01","objectives":["MAN-019","MAN-020","MAN-021","MAN-022","MAN-023"],"title":"Windows Autopilot: identity to first sign-in","scenario":"Seven new Windows laptops arrive for Accounting. They should show an organization-branded setup, receive required apps, and be ready when the employees sign in.","mental":"Autopilot controls supported OOBE provisioning. Profile eligibility and device grouping come before employee sign-in; the Enrollment Status Page can hold setup until selected apps/policies finish.","why":"Choosing an incompatible deployment mode or blocking the wrong app can strand every new hire at setup.","prerequisites":"Validate device registration, assignment, supported Windows hardware, user identity/licensing, network, ESP and required app installation behavior.","verify":"Correct device gets the intended profile, enrolls through OOBE, required apps report installed, and the user reaches the desktop with device check-in evidence.","failure":"ESP is stuck waiting for a required Win32 application.","recovery":"Inspect app detection and installation context, ESP tracked apps, assignment, timeouts and device-side logs; avoid repeated resets without correcting the block.","risk":"Self-deploying requires supported prerequisites and is not a drop-in substitute for a user-driven employee laptop flow.","settings":[{"prompt":"New-hire deployment mode","choices":[{"text":"User-driven Windows Autopilot","why":"Employees sign in during guided provisioning; appropriate for individually assigned laptops."},{"text":"Self-deploying kiosk-style mode","why":"Not appropriate when the flow depends on assigned employee sign-in."},{"text":"Mac Automated Device Enrollment","why":"Apple-specific workflow."}],"answer":0},{"prompt":"App requirement","choices":[{"text":"Pilot the blocking required apps and their detection rules","why":"ESP tracked required apps must install successfully to avoid blocking onboarding."},{"text":"Mark all applications as ESP blocking immediately","why":"An untested failure may delay every enrollment."},{"text":"Install personal apps during OOBE","why":"Not the purpose of corporate device preparation."}],"answer":0},{"prompt":"Confirm success","choices":[{"text":"Examine device profile assignment, ESP/app status, Intune check-in","why":"These show provisioning and management actually happened."},{"text":"Check only the shipping serial number","why":"Inventory is not evidence of completed OOBE enrollment."},{"text":"Check only employee email delivery","why":"Email is unrelated to Autopilot result."}],"answer":0}],"incident":{"prompt":"ESP blocked; which evidence is most useful?","choices":[{"text":"Failed required app installation and detection result","why":"The failing tracked app is often the immediate blocking condition."},{"text":"Assume the user forgot a password","why":"User errors are only one possibility and need evidence."},{"text":"Delete all Autopilot records","why":"Destructive and not a diagnosis."}],"answer":0},"concept":{"prompt":"What does ESP contribute?","choices":[{"text":"A checkpoint for required provisioning work","why":"It can block progress until selected work reports completion."},{"text":"An alternate identity provider","why":"ESP is not an Entra identity service."},{"text":"Automatic hardware repair","why":"ESP cannot repair failed hardware."}],"answer":0},"domain":"management","doc":"https://learn.microsoft.com/en-us/search/?terms=Windows%20Autopilot%3A%20identity%20to%20first%20sign-in%20Microsoft%20Intune"},{"id":"M02","objectives":["MAN-027","MAN-028","MAN-029","MAN-030","MAN-032"],"title":"Settings Catalog and assignment filters","scenario":"Northstar needs a browser restriction on corporate Windows laptops, but the policy must skip personally owned Windows PCs and all Macs.","mental":"Profiles define desired settings; groups provide initial targeting; assignment filters can include/exclude device attributes for supported assignments. Conflicts occur when competing settings target the same device.","why":"Filtering protects the pilot boundary, and investigating per-setting results prevents a false sense of success.","prerequisites":"Confirm platform, profile type, supported setting, group, filter behavior, and device eligibility. Test one match and one non-match.","verify":"Corporate Windows receives the intended setting, personal Windows is excluded, and no conflict appears in per-setting device status.","failure":"One laptop reports Conflict despite showing two assigned profiles.","recovery":"Compare effective profiles, matching groups/filters and incompatible setting values. Remove the overlap in pilot rather than adding a third policy.","risk":"Do not interpret policy Created or Assigned as proof the setting applied to the targeted OS.","settings":[{"prompt":"Profile platform","choices":[{"text":"Windows Settings Catalog with supported setting","why":"Settings Catalog supports many Windows policy settings with Intune reporting."},{"text":"macOS configuration profile for Windows machines","why":"A different platform profile does not configure Windows."},{"text":"Only a compliance policy","why":"Compliance measures posture; it is not a replacement for every configuration setting."}],"answer":0},{"prompt":"Assignment boundary","choices":[{"text":"Include corporate Windows and exclude personal devices","why":"Use a supported group/filter combination and verify membership."},{"text":"Assign all devices without exclusion","why":"Personal and unsupported devices may be targeted."},{"text":"Use only scope tags","why":"Scope tags govern admin scoping rather than deployment targeting."}],"answer":0},{"prompt":"Confirm state","choices":[{"text":"Per-setting status on matched and excluded devices","why":"Positive and negative tests show expected application and filtering behavior."},{"text":"Only confirm the policy has a name","why":"Names are not device-side evidence."},{"text":"Check an unrelated phone","why":"The targeted OS is Windows."}],"answer":0}],"incident":{"prompt":"What should be investigated when Conflict appears?","choices":[{"text":"Two targeted profiles configuring incompatible values","why":"Per-setting conflict usually requires resolving overlapping assignments or settings."},{"text":"A lack of devices in the company","why":"The device is reporting multiple profiles, so it exists."},{"text":"Use a different logo on the page","why":"Branding does not change policy evaluation."}],"answer":0},"concept":{"prompt":"Why are assignment filters helpful?","choices":[{"text":"They refine targeting by supported device properties","why":"A policy should not automatically touch every device in a large group."},{"text":"They permanently elevate administrator privileges","why":"Filters do not assign RBAC roles."},{"text":"They repair devices by themselves","why":"They only affect assignment applicability."}],"answer":0},"domain":"management","doc":"https://learn.microsoft.com/en-us/search/?terms=Settings%20Catalog%20and%20assignment%20filters%20Microsoft%20Intune"},{"id":"M03","objectives":["MAN-025","MAN-026"],"title":"Windows 365 Cloud PC provisioning","scenario":"Northstar hires remote accountants who need managed Windows desktops but have low-end personal laptops. You must plan Cloud PCs without accidentally creating chargeable resources.","mental":"A Cloud PC is a licensed, provisioned remote Windows environment. A provisioning policy chooses image, network and assignment; capacity, licensing and networking prerequisites matter.","why":"Cloud PC setup can fail even when an assigned user is otherwise licensed for Intune.","prerequisites":"Confirm Windows 365 licensing and SKU, supported image, networking model, identity, resource availability and group assignment before any real deployment.","verify":"Cloud PC shows provisioned/ready for the assigned user, is managed according to policy, and remote connection succeeds.","failure":"Cloud PC provisioning fails with network connectivity validation errors.","recovery":"Inspect provisioning policy network choice, Azure network connection health where applicable, DNS/reachability, identity and licensing rather than deleting user accounts.","risk":"Never enable a paid Windows 365 license as part of this educational simulation.","settings":[{"prompt":"Delivery model","choices":[{"text":"Licensed Windows 365 Cloud PC provisioning policy","why":"A Cloud PC is a service-backed Windows desktop with specific setup requirements."},{"text":"Deploy Windows Autopilot to personal laptop only","why":"Autopilot does not provision a cloud-hosted Windows 365 PC."},{"text":"Create a Teams channel","why":"Teams does not provision desktops."}],"answer":0},{"prompt":"Preflight","choices":[{"text":"Validate license, image, identity and networking prerequisites","why":"These prerequisites must line up before provisioning is possible."},{"text":"Skip network validation","why":"Network model and reachability can block provisioning."},{"text":"Choose a random unsupported image","why":"Only supported image configurations should be used."}],"answer":0},{"prompt":"Evidence","choices":[{"text":"Provisioning status and successful user connection","why":"Provisioned state plus a working session tests both service and experience."},{"text":"Only inspect the purchased license","why":"A license does not prove provisioning succeeded."},{"text":"Count an Intune policy name","why":"Policy existence does not prove cloud desktop readiness."}],"answer":0}],"incident":{"prompt":"What most directly explains network validation failure?","choices":[{"text":"Network/DNS/reachability configuration mismatch","why":"Inspect health checks for the selected network model."},{"text":"User profile picture is missing","why":"Profile photos do not determine Cloud PC networking."},{"text":"Incorrect Teams meeting timezone","why":"Meeting metadata is unrelated to provisioning."}],"answer":0},"concept":{"prompt":"Why distinguish Windows 365 from Intune?","choices":[{"text":"One provisions hosted Cloud PCs; the other helps manage endpoints","why":"Licenses and operational workflows differ even when they integrate."},{"text":"Both replace network connectivity","why":"Neither removes the need for access to services."},{"text":"They are the same service under two names","why":"Distinct Microsoft products."}],"answer":0},"domain":"management","doc":"https://learn.microsoft.com/en-us/search/?terms=Windows%20365%20Cloud%20PC%20provisioning%20Microsoft%20Intune"},{"id":"M04","objectives":["MAN-033","MAN-034","MAN-035","MAN-036","MAN-037","MAN-038"],"title":"Intune Suite: Endpoint Privilege Management pilot","scenario":"A standard user needs to install a trusted line-of-business updater without receiving permanent local administrator rights. Support needs an auditable elevation path.","mental":"Endpoint Privilege Management (EPM) enables controlled elevation of specified processes using policy-defined trust and approval. It is an optional licensed capability.","why":"Temporary task-scoped elevation reduces standing privileges and creates evidence for review.","prerequisites":"Confirm EPM entitlement, prerequisites, policy identity, target elevation rules, signed/trusted executable and pilot assignment.","verify":"Authorized process elevation is recorded; unapproved executables remain blocked or require the configured support approval workflow.","failure":"The updater is denied despite a configured elevation rule.","recovery":"Inspect file matching, signer/hash/path rules, device EPM health, assignment and approval requirements.","risk":"Do not solve one updater request by making every employee a local administrator; do not enable a paid trial without approval.","settings":[{"prompt":"Least-privilege solution","choices":[{"text":"Endpoint Privilege Management targeted elevation","why":"EPM can grant policy-scoped elevation without permanent admin membership."},{"text":"Permanent local administrator for every user","why":"Creates unnecessary persistent risk."},{"text":"Disable Microsoft Defender for all users","why":"Disabling protection is not an elevation strategy."}],"answer":0},{"prompt":"Pilot control","choices":[{"text":"Approved executable match plus limited device assignment","why":"Process trust conditions and group targeting should be narrow."},{"text":"Allow all executables with no checks","why":"Makes elevation policy dangerously broad."},{"text":"Send the admin password by email","why":"Credential sharing is not a managed elevation workflow."}],"answer":0},{"prompt":"Verification","choices":[{"text":"Elevation audit and user/device policy results","why":"Audit events and results show what happened to the actual request."},{"text":"Only confirm the updater icon appears","why":"A desktop icon does not prove policy-driven elevation."},{"text":"Only read the purchase order","why":"Licensing paperwork does not prove configuration."}],"answer":0}],"incident":{"prompt":"EPM denies an approved updater; what next?","choices":[{"text":"Check policy file matching and EPM client health","why":"The signer/hash/path and assignment must match the executable."},{"text":"Make the user Global Administrator","why":"Unnecessary permission elevation."},{"text":"Reinstall Windows on the entire department","why":"Unsupported as an initial troubleshooting step."}],"answer":0},"concept":{"prompt":"Why use EPM instead of permanent admin?","choices":[{"text":"Task-specific privilege with auditing","why":"Reduces standing privilege and provides governance."},{"text":"All users become security administrators","why":"That is not least privilege."},{"text":"EPM removes all attack surface","why":"Privilege control does not eliminate all risk."}],"answer":0},"domain":"management","doc":"https://learn.microsoft.com/en-us/search/?terms=Intune%20Suite%3A%20Endpoint%20Privilege%20Management%20pilot%20Microsoft%20Intune"},{"id":"M05","objectives":["MAN-039","MAN-040","MAN-042","MAN-045"],"title":"Remote actions and evidence preservation","scenario":"A company laptop is reported lost. Another laptop needs a routine sync. You must choose actions with different impact and obtain the correct authorization.","mental":"Sync asks a device to check in. Retire removes management and selected corporate data according to platform/management; wipe resets/reprovisions with materially different consequences.","why":"The impact of a remote action can be irreversible. The correct action depends on ownership, incident severity, and recovery goals.","prerequisites":"Confirm ownership, device identity, current service connectivity, administrator role, backup/recovery options and incident ticket approval.","verify":"Routine sync updates policy telemetry; lost corporate laptop action follows approved incident playbook with recorded audit entry.","failure":"A helpdesk technician selects Wipe for a personal phone with work data.","recovery":"Pause action, confirm ownership and enrollment type, review selective wipe/retire capabilities and escalation.","risk":"Never issue a destructive wipe as a shortcut for a policy check-in problem.","settings":[{"prompt":"Routine refresh","choices":[{"text":"Sync device","why":"Requests the MDM channel to check in and retrieve policy changes."},{"text":"Wipe device","why":"Destroys/rewrites local device state and is not a diagnostic sync."},{"text":"Rotate the user password for the whole tenant","why":"Unrelated broad identity action."}],"answer":0},{"prompt":"Lost laptop workflow","choices":[{"text":"Follow incident-approved action for confirmed corporate device","why":"Ownership, user impact and data risk determine whether wipe, lock, or other action is appropriate."},{"text":"Wipe any matching device name immediately","why":"Unverified identity can cause irreparable damage."},{"text":"Disable all Intune roles","why":"Not a targeted lost-device response."}],"answer":0},{"prompt":"Audit evidence","choices":[{"text":"Record ticket, device identifier, action, actor and result","why":"Remote action audit protects accountability and confirms outcome."},{"text":"Only tell the user it should work","why":"Verbal assurance is not execution evidence."},{"text":"Erase all logs after action","why":"Destroys evidence and weakens response."}],"answer":0}],"incident":{"prompt":"Wipe selected on a personal phone; safest response?","choices":[{"text":"Stop and verify ownership and appropriate selective corporate-data action","why":"Distinguish personal and corporate data before destructive action."},{"text":"Click Confirm immediately","why":"May erase personal data unnecessarily."},{"text":"Ignore the incident entirely","why":"Company data still needs protection."}],"answer":0},"concept":{"prompt":"Why are remote actions risk-ranked?","choices":[{"text":"Different actions have different reversibility and data impact","why":"A sync and a wipe should never share the same confirmation workflow."},{"text":"All device actions are harmless","why":"Some actions are destructive."},{"text":"Only the button color differs","why":"Effects differ materially."}],"answer":0},"domain":"management","doc":"https://learn.microsoft.com/en-us/search/?terms=Remote%20actions%20and%20evidence%20preservation%20Microsoft%20Intune"},{"id":"S01","objectives":["SEC-046","SEC-048","SEC-049","SEC-050","SEC-051","SEC-052","SEC-053"],"title":"Defender, firewall and attack surface reduction","scenario":"The security team needs malware protection and EDR for Windows pilots. A new ASR block rule is proposed, but it might interrupt accounting macros.","mental":"Antivirus, endpoint detection/response, firewall, ASR and baselines defend different layers. An ASR rule may start in audit mode to assess impact before enforcement.","why":"An all-at-once restrictive rollout can break legitimate work while masking which layer caused the change.","prerequisites":"Confirm licensing and Defender onboarding, device eligibility, pilot scope, baseline conflicts and planned exclusions/rollbacks.","verify":"Defender onboarding health is good, AV/EDR policy reports success, ASR audit events reveal impact, and enforcement is rolled out intentionally.","failure":"Accounting payroll macro is blocked immediately after an ASR policy change.","recovery":"Inspect ASR rule ID, mode, event/log details, device policy assignments and whether a specific legitimate app needs a justified exception.","risk":"Do not disable all Defender policies or blanket-exclude entire system folders merely to stop a single warning.","settings":[{"prompt":"Initial ASR rollout","choices":[{"text":"Audit mode for a restricted pilot","why":"Audit events reveal legitimate impact before full blocking."},{"text":"Block all devices immediately","why":"An untested rule may interrupt business workflows."},{"text":"Disable all exploit protection","why":"Weakens defenses unrelated to the particular rule."}],"answer":0},{"prompt":"Security layering","choices":[{"text":"Use distinct AV, EDR, firewall and ASR controls","why":"Each protects a different attack/response layer."},{"text":"Use one compliance rule for every security feature","why":"Compliance cannot substitute for each protection mechanism."},{"text":"Just rename Defender policies","why":"Names are not control effectiveness."}],"answer":0},{"prompt":"Verification","choices":[{"text":"Review Defender onboarding, policy status and ASR event evidence","why":"Device-side and service evidence show real application and side effects."},{"text":"Check that the policy object was saved","why":"A saved object does not prove enforcement."},{"text":"Only ask the employee if laptop feels faster","why":"Performance anecdotes cannot verify threat protection."}],"answer":0}],"incident":{"prompt":"Legitimate macro is blocked; root investigation?","choices":[{"text":"ASR rule and event with related assignment","why":"The active block rule and event evidence identify the source of disruption."},{"text":"Disable all security solutions","why":"Not proportionate or investigative."},{"text":"Create a second identical ASR policy","why":"Duplicating may worsen conflicts."}],"answer":0},"concept":{"prompt":"Why use audit mode first?","choices":[{"text":"It measures expected impact before enforcement","why":"A staged rollout improves security without unexpected downtime."},{"text":"It guarantees malware is fully blocked","why":"Audit mode records rather than blocks selected behavior."},{"text":"It bypasses licensing requirements","why":"Audit mode does not remove prerequisites."}],"answer":0},"domain":"security","doc":"https://learn.microsoft.com/en-us/search/?terms=Defender%2C%20firewall%20and%20attack%20surface%20reduction%20Microsoft%20Intune"},{"id":"S02","objectives":["SEC-054","SEC-055","SEC-056","SEC-057","SEC-058","SEC-059","SEC-060"],"title":"Update rings, quality updates and restart policy","scenario":"Northstar wants security updates promptly but cannot reboot accounting laptops during monthly close. It needs pilot-first rollout and compliance monitoring.","mental":"Update rings define delivery/restart experience; feature/quality policies target update versions/deadlines where supported. Reporting is needed to distinguish assigned from installed.","why":"An aggressive forced reboot might disrupt business workflows. Deferring updates forever creates security exposure.","prerequisites":"Confirm eligible Windows versions, supported update policy type, deployment group, restart controls, update telemetry and fallback rollout.","verify":"Pilot installs updates, restarts inside communicated maintenance windows, and reports version/restart compliance; exceptions are investigated.","failure":"Devices show update assigned but pending restart for several days.","recovery":"Inspect deadlines, active hours, device check-in, reboot pending flags, conflicting policies and update telemetry before changing the whole rollout.","risk":"Do not use blanket update pauses without expiry or approval.","settings":[{"prompt":"Rollout sequence","choices":[{"text":"Pilot ring followed by broad rollout","why":"Staged distribution catches compatibility and servicing issues."},{"text":"All devices at once, no reporting","why":"Blasts an unvalidated update fleet-wide."},{"text":"Only apply mobile FOTA policy to Windows","why":"Android FOTA does not govern Windows updates."}],"answer":0},{"prompt":"Restart experience","choices":[{"text":"Configured deadlines and active-hours policy","why":"Business needs must be balanced with security deadlines."},{"text":"Disable all restarts permanently","why":"Blocks servicing and can prevent remediation."},{"text":"Force immediate restart during payroll","why":"Unexpected interruption is avoidable."}],"answer":0},{"prompt":"Verify update application","choices":[{"text":"Check installed version and update status on representative devices","why":"Policy assignment and actual OS patch state are different measures."},{"text":"Only count active update rings","why":"A ring count does not indicate installed updates."},{"text":"Only read Slack messages","why":"Chat reports are insufficient technical evidence."}],"answer":0}],"incident":{"prompt":"Update assigned but not complete; likely blocker?","choices":[{"text":"Pending restart or device servicing state","why":"Check update telemetry and restart requirements."},{"text":"The user renamed a Word document","why":"Unrelated to Windows servicing."},{"text":"Group name includes Accounting","why":"A department name is not in itself an error."}],"answer":0},"concept":{"prompt":"Why are update rings and feature updates different?","choices":[{"text":"One controls servicing behavior; the other can target feature versions","why":"The policies have distinct intent and configuration."},{"text":"Both are identical rename operations","why":"They are not simply labels."},{"text":"A feature update controls user passwords","why":"It manages operating-system releases."}],"answer":0},"domain":"security","doc":"https://learn.microsoft.com/en-us/search/?terms=Update%20rings%2C%20quality%20updates%20and%20restart%20policy%20Microsoft%20Intune"},{"id":"A01","objectives":["APP-061","APP-062","APP-064","APP-066","APP-069"],"title":"Win32 application deployment and detection","scenario":"Northstar deploys a payroll Win32 app. The installation finishes with exit code 0, but Intune repeatedly reports failed installation and retries.","mental":"A Win32 app has package/install command and requirements; the detection rule is independent evidence of successful installation. Wrong detection can cause retries despite a successful installer.","why":"An installer exiting successfully is not proof that Intune can detect the app in the correct context.","prerequisites":"Confirm package format, install/uninstall commands, 32/64-bit context, requirements, dependencies, detection method and pilot assignment.","verify":"Intune app report shows Installed, detection confirms expected file/registry/MSI code, and the payroll app launches on the test device.","failure":"Installer log says success, app status says failed or keeps retrying.","recovery":"Inspect Intune Management Extension logs and configured detection method; compare real installed artifacts and required execution context.","risk":"Do not widen assignments until install, uninstall and detection are tested and reversible.","settings":[{"prompt":"Installation proof","choices":[{"text":"A detection rule matching the actual installed artifact","why":"Intune must detect successful installation using a reliable indicator."},{"text":"Trust exit code alone","why":"Exit codes do not always satisfy Intune detection."},{"text":"Check whether the app icon has the company logo","why":"Branding cannot validate installation."}],"answer":0},{"prompt":"Pilot assignment","choices":[{"text":"Small test group with Required intent","why":"An intentional, scoped required deployment validates behavior before scale."},{"text":"Assign all users without checks","why":"Large initial blast increases impact."},{"text":"Use only an administrator role scope tag","why":"Scope tags do not assign apps."}],"answer":0},{"prompt":"Failure diagnosis","choices":[{"text":"Review IME logs and file/registry/MSI detection evidence","why":"Logs and artifacts isolate why reported installation differs from reality."},{"text":"Delete every app record","why":"Destructive and unrelated to diagnosis."},{"text":"Change the laptop wallpaper","why":"Not relevant to Win32 detection."}],"answer":0}],"incident":{"prompt":"Installer returns zero but app repeatedly retries—why?","choices":[{"text":"Detection rule fails to match the installed state","why":"Required Win32 detection controls Installed reporting and retry behavior."},{"text":"The user has too many browser tabs","why":"Unrelated to detection."},{"text":"The company laptop is blue","why":"Device color cannot explain installation retry."}],"answer":0},"concept":{"prompt":"Why must app detection be tested independently?","choices":[{"text":"Install execution and installed-state verification are distinct","why":"An exit code is only one piece of evidence."},{"text":"It is purely a cosmetic report preference","why":"Detection can affect subsequent install behavior."},{"text":"Detection only applies to Android","why":"Win32 app detection is a Windows Intune mechanism."}],"answer":0},"domain":"applications","doc":"https://learn.microsoft.com/en-us/search/?terms=Win32%20application%20deployment%20and%20detection%20Microsoft%20Intune"},{"id":"A02","objectives":["APP-063","APP-068","APP-070","APP-071","APP-072"],"title":"BYOD app protection and Conditional Access","scenario":"A contractor can read corporate email on their personal phone. Security must prevent copying company data to personal apps without enrolling or wiping the phone.","mental":"MAM app protection governs work data inside supported apps. Conditional Access can require approved client/app protection signals, depending on platform and scenario.","why":"Full device enrollment and corporate wipe may be excessive when app-level controls meet the data-protection requirement.","prerequisites":"Confirm supported apps, app protection policy assignment, account/identity licensing, CA grant selection and enrollment status.","verify":"Contractor’s approved app has protected copy/paste and save-as behavior; unmanaged personal apps do not receive company data.","failure":"Corporate email works but copy/paste into personal notes is still permitted.","recovery":"Inspect app protection policy targeting, app coverage, user identity, applicable CA controls and app check-in/evaluation logs.","risk":"Do not assume an Intune MDM device record is necessary for every MAM scenario.","settings":[{"prompt":"Protect corporate app data","choices":[{"text":"Intune app protection policy for supported apps","why":"MAM can govern supported corporate app data on BYOD."},{"text":"Full-device wipe policy as the only data control","why":"Unnecessarily broad for contractor BYOD."},{"text":"No policy, rely on a training email","why":"Training is useful but does not enforce technical controls."}],"answer":0},{"prompt":"Identity access policy","choices":[{"text":"Applicable CA policy requiring app protection where supported","why":"Identity controls can require the intended protected-app path."},{"text":"Allow all clients with no restrictions","why":"Unprotected clients may bypass desired app controls."},{"text":"Grant Global Administrator to contractor","why":"Inappropriate authorization."}],"answer":0},{"prompt":"Verification","choices":[{"text":"Test managed-to-unmanaged data transfer and sign-in logs","why":"Real behavior matters more than merely seeing policies listed."},{"text":"Only check Outlook is installed","why":"An installed app does not prove APP enforcement."},{"text":"Only verify user can view a website","why":"Web access says little about corporate data containment."}],"answer":0}],"incident":{"prompt":"Work data still copies to personal apps—what investigate?","choices":[{"text":"APP scope and user/app targeting or evaluation","why":"App protection must actually apply to the identity and supported app."},{"text":"Windows Autopilot deployment mode","why":"Autopilot is not the relevant BYOD mechanism."},{"text":"A Windows feature update","why":"Unrelated to iOS/Android app data protection."}],"answer":0},"concept":{"prompt":"Why is MAM useful without enrollment?","choices":[{"text":"App-data controls can operate on supported BYOD apps","why":"This supports data security with less personal-device management."},{"text":"MAM provides full physical device control","why":"App protection is not identical to MDM."},{"text":"MAM removes all need for identity controls","why":"Identity and app protection complement each other."}],"answer":0},"domain":"applications","doc":"https://learn.microsoft.com/en-us/search/?terms=BYOD%20app%20protection%20and%20Conditional%20Access%20Microsoft%20Intune"},{"id":"O01","objectives":["OPE-073","OPE-077","OPE-080"],"title":"PowerShell, Graph and remediation automation","scenario":"Northstar sees dozens of Windows laptops with a known misconfiguration. The team wants to detect it, remediate safely and report actual device outcomes.","mental":"PowerShell/Graph automation requires least-privilege permissions and explicit success criteria. Intune Remediations commonly use a detection script to decide if a remediation should run.","why":"Blindly executing a fix on every endpoint can worsen an issue; detection and rollback make automation auditable.","prerequisites":"Confirm execution context, supported OS, run schedule, permissions, logging, detection exit codes and pilot targeting.","verify":"Detection identifies affected endpoints, remediation changes only intended settings, follow-up detection confirms the repair, and audit/report status is available.","failure":"All targeted devices appear remediated, but the underlying registry value is unchanged.","recovery":"Inspect detection/repair script logic, execution context, script exit codes, logs, scheduling and actual target state.","risk":"Never grant unnecessary Graph application permissions or run destructive scripts across the tenant by default.","settings":[{"prompt":"Automation approach","choices":[{"text":"Detect first, remediate conditionally, verify afterward","why":"A safe detection/repair loop limits unintended changes."},{"text":"Run the change everywhere immediately","why":"Broad unverified remediation risks collateral impact."},{"text":"Rely on a success toast message","why":"A message is not evidence of corrected device state."}],"answer":0},{"prompt":"Permissions and rollout","choices":[{"text":"Least-privilege Graph/Intune role and pilot devices","why":"Permissions and scope should follow documented operational need."},{"text":"Grant global app permissions for convenience","why":"Excess privilege increases security risk."},{"text":"Run remediation from personal accounts","why":"Unmanaged credentials weaken accountability."}],"answer":0},{"prompt":"Proof remediation succeeded","choices":[{"text":"Re-run detection and inspect actual setting/evidence","why":"A state measurement after remediation is stronger than execution success alone."},{"text":"Check script file name","why":"A name does not prove repair."},{"text":"Check only job started status","why":"Started differs from successful and verified."}],"answer":0}],"incident":{"prompt":"Job says success but state unchanged; what next?","choices":[{"text":"Review script detection logic, context and post-state","why":"An exit code alone cannot guarantee desired state."},{"text":"Repeat without limit","why":"Repeats may hide or worsen a logic bug."},{"text":"Turn off BitLocker fleet-wide","why":"Unrelated and unsafe."}],"answer":0},"concept":{"prompt":"Why separate detection and remediation?","choices":[{"text":"To limit changes to affected devices and validate fixes","why":"A detection-first workflow improves repeatability and safety."},{"text":"Because Graph cannot write data","why":"Graph supports appropriate operations with permission."},{"text":"Because all endpoints are always broken","why":"Only affected devices need work."}],"answer":0},"domain":"operations","doc":"https://learn.microsoft.com/en-us/search/?terms=PowerShell%2C%20Graph%20and%20remediation%20automation%20Microsoft%20Intune"},{"id":"O02","objectives":["OPE-074","OPE-075","OPE-076"],"title":"Security Copilot agents and human decisions","scenario":"A Security Copilot agent suggests disabling a restrictive policy based on a performance anomaly. The admin must investigate before approving the change.","mental":"Agent output is an investigation input, not an automatic source of truth. Verify data provenance, scope, permissions, real device evidence and risk before action.","why":"An AI recommendation can be plausible but unsafe if generated from incomplete telemetry.","prerequisites":"Confirm entitlements, authorized admin roles, suggested action scope, supporting data freshness, and independent technical evidence.","verify":"The administrator records the recommendation, checks device metrics and policy effect, chooses a scoped pilot or rejects the suggestion with rationale, then reviews the result.","failure":"Agent recommends disabling the company-wide security baseline to fix one slow laptop.","recovery":"Check device-level performance data, assignment timing, correlated security events and whether a narrower remediation exists.","risk":"Never let a recommendation bypass change control or suppress a security policy without supporting evidence.","settings":[{"prompt":"Response to AI suggestion","choices":[{"text":"Review evidence and test a narrow reversible change","why":"Human oversight is essential for consequential security settings."},{"text":"Approve immediate company-wide disablement","why":"Unsupported fleet-wide risk based on one suggestion."},{"text":"Ignore telemetry but still deploy","why":"Not an evidence-based decision."}],"answer":0},{"prompt":"Evidence to request","choices":[{"text":"Relevant device signals, timeframe and policy scope","why":"Specific data can validate or reject a proposed causal relationship."},{"text":"Only the agent confidence adjective","why":"A subjective rating is insufficient."},{"text":"Only a user selfie","why":"Not relevant to endpoint performance."}],"answer":0},{"prompt":"Close the loop","choices":[{"text":"Document approval decision, pilot result and rollback","why":"A traceable decision plus verified impact makes operations accountable."},{"text":"Delete recommendation history","why":"Removes audit evidence."},{"text":"Assume nothing changed after deployment","why":"You must observe consequences."}],"answer":0}],"incident":{"prompt":"Why is broad policy removal unsafe here?","choices":[{"text":"A single-device symptom does not prove fleet-wide baseline is the cause","why":"Scope and causality must be established before disabling controls."},{"text":"Security baselines never protect devices","why":"They provide security configuration guidance and deployment."},{"text":"AI recommendations are binding commands","why":"Admins remain accountable for decisions."}],"answer":0},"concept":{"prompt":"What should accompany AI recommendations?","choices":[{"text":"Corroborating evidence, least privilege and human approval","why":"Agentic tools support, not replace, accountable administration."},{"text":"No traceable records","why":"Auditability matters."},{"text":"Automatic access to all tenant secrets","why":"Unnecessary and dangerous."}],"answer":0},"domain":"operations","doc":"https://learn.microsoft.com/en-us/search/?terms=Security%20Copilot%20agents%20and%20human%20decisions%20Microsoft%20Intune"},{"id":"O03","objectives":["MAN-044","OPE-078","OPE-079","OPE-081","OPE-082","OPE-083"],"title":"Endpoint Analytics, KQL and service health","scenario":"Northstar helpdesk reports slow startup times across Accounting. An alert also indicates device enrollment failures, but the admin must determine whether these events are related.","mental":"Analytics measures endpoint health and user experience. Device queries and reports support focused investigation; service health helps distinguish tenant-wide incidents from local problems.","why":"A single dashboard number or average score can hide cohorts and timing. Correlation does not automatically prove one policy caused the problem.","prerequisites":"Confirm data collection eligibility and report freshness, select affected devices, compare baselines, inspect service communication and route-specific logs.","verify":"Startup metrics are compared before/after intervention; device cohort and incident timeline are documented; actionable alerts have appropriate owners.","failure":"Startup score drops and one alert occurs, but no device logs are captured.","recovery":"Inspect per-device metrics, recent changes, errors, service health advisories and a representative diagnostic log sample.","risk":"Never declare a fleet outage based only on a stale performance chart.","settings":[{"prompt":"Investigation start","choices":[{"text":"Filter to affected cohort and baseline period","why":"Comparing similar devices over time reveals distribution and trend."},{"text":"Ignore device membership and compare everyone","why":"Mixed cohorts can hide or fabricate trends."},{"text":"Immediately reset all laptops","why":"Destructive without evidence."}],"answer":0},{"prompt":"Cross-check tenant health","choices":[{"text":"Inspect Intune service health and communications","why":"Service incidents can affect management/reporting independently of client startup."},{"text":"Use a generic search-engine result alone","why":"Not authoritative for the tenant."},{"text":"Only check a printer queue","why":"Not relevant to Intune tenant communications."}],"answer":0},{"prompt":"Proof of improvement","choices":[{"text":"Measure device-level startup and reliability after the change","why":"Before/after metrics plus change history support causal investigation."},{"text":"Count how many graphs have green bars","why":"Visual color alone does not establish improved experience."},{"text":"Check only how many policies exist","why":"Policy inventory is not UX impact evidence."}],"answer":0}],"incident":{"prompt":"Startup score falls but logs missing; next action?","choices":[{"text":"Collect representative device diagnostics and correlate changes","why":"Evidence is needed before attributing the trend to a policy or service."},{"text":"Delete all analytical data","why":"Destroys investigative context."},{"text":"Silence alerts without investigation","why":"Hides ongoing impact."}],"answer":0},"concept":{"prompt":"Why segment analytics by cohort?","choices":[{"text":"Mixed populations may hide the devices actually impacted","why":"Cohort comparisons prevent misleading averages."},{"text":"Scores always prove a single root cause","why":"Metrics identify symptoms, not always cause."},{"text":"Device names determine reliability","why":"Names do not govern performance."}],"answer":0},"domain":"operations","doc":"https://learn.microsoft.com/en-us/search/?terms=Endpoint%20Analytics%2C%20KQL%20and%20service%20health%20Microsoft%20Intune"},{"id":"M06","objectives":["MAN-031"],"title":"Specialty devices: Teams Rooms, HoloLens and rugged endpoints","scenario":"Northstar has a Teams Rooms conferencing console and Zebra field scanners. The helpdesk wants to apply a generic laptop security profile to both.","mental":"Special-purpose hardware runs specialized OS/app experiences. Device platform, supported enrollment mode and vendor guidance determine which Intune controls are applicable.","why":"An unsupported generic profile may report Not applicable or disrupt a dedicated workflow.","prerequisites":"Identify exact device model, OS, enrollment ownership/mode, licensing, vendor guidance and required application experience before assignment.","verify":"Eligible specialty devices receive only supported targeted policies; Not applicable is recorded rather than treated as success.","failure":"A Teams Rooms device reports Not applicable for a standard Windows desktop configuration.","recovery":"Inspect supported OS/platform, Intune management integration, profile applicability and device management channel.","risk":"Do not force broad workstation baseline policies onto conferencing or kiosk systems without a validated pilot.","settings":[{"prompt":"Profile design","choices":[{"text":"Choose supported device-specific settings and enrollment","why":"Specialty endpoints need compatible policy settings and management method."},{"text":"Apply every Windows laptop policy unchanged","why":"Platform or usage differences may make some settings unsupported."},{"text":"Disable all restrictions","why":"Removes appropriate security controls without a plan."}],"answer":0},{"prompt":"Target scope","choices":[{"text":"Use dedicated specialty-device groups","why":"Dedicated assignments reduce unintentional kiosk or meeting-room disruption."},{"text":"Assign All users","why":"User targeting may not fit dedicated/shared devices."},{"text":"Use only a scope tag","why":"Scope tags are not deployment assignments."}],"answer":0},{"prompt":"Verification","choices":[{"text":"Validate supported setting result and core device function","why":"A successful report should be paired with a working meeting/kiosk scenario."},{"text":"Only see the device name","why":"Naming cannot prove policy compatibility."},{"text":"Only check a corporate phone","why":"Different device class."}],"answer":0}],"incident":{"prompt":"Why does a workstation setting say Not applicable?","choices":[{"text":"The specialty platform or edition does not support that setting","why":"Intune reports Not applicable for unsupported policy/device combinations."},{"text":"Because the conference room is quiet","why":"Not technical evidence."},{"text":"Because Microsoft 365 license is always missing","why":"Licensing may matter, but setting applicability must be checked directly."}],"answer":0},"concept":{"prompt":"What is the most important first step for specialty endpoints?","choices":[{"text":"Validate exact supported platform and enrollment path","why":"Management features differ across dedicated device families."},{"text":"Assume all managed devices behave like laptops","why":"Unsupported assumption."},{"text":"Apply all security controls and hope","why":"Risks business downtime."}],"answer":0},"domain":"management","doc":"https://learn.microsoft.com/en-us/search/?terms=Specialty%20devices%3A%20Teams%20Rooms%2C%20HoloLens%20and%20rugged%20endpoints%20Microsoft%20Intune"},{"id":"M07","objectives":["MAN-024","MAN-041"],"title":"Windows 11 upgrades and Defender intelligence actions","scenario":"Northstar is upgrading older managed Windows PCs. Meanwhile, an outbreak requires updating antivirus security intelligence on an eligible device without forcing an OS feature upgrade.","mental":"Feature upgrades and Defender security-intelligence updates are separate operations; one changes the operating system version, the other refreshes antivirus detection signatures.","why":"Conflating emergency security-intelligence refresh with broad Windows feature upgrades can cause unnecessary disruption.","prerequisites":"Check current Windows build, OS/hardware eligibility, policy assignment, update readiness, endpoint connectivity and Defender health.","verify":"Targeted devices move to an approved Windows release through planned rollout, while emergency AV intelligence action reports success independently.","failure":"A workstation is not eligible for the intended Windows 11 upgrade.","recovery":"Inspect system requirements, safeguard holds, compatibility reports, update policy targeting and client-side update errors.","risk":"Never force unsupported feature upgrades or assume updating Defender signatures patches the Windows OS.","settings":[{"prompt":"Planned OS upgrade","choices":[{"text":"Windows feature update policy scoped to eligible pilot","why":"Feature upgrades require compatibility validation and a measured rollout."},{"text":"Defender intelligence refresh only","why":"Signatures do not upgrade the operating system."},{"text":"Unplanned factory reset","why":"Reset is not a version-targeting policy."}],"answer":0},{"prompt":"Urgent signature refresh","choices":[{"text":"Defender security intelligence update action on selected devices","why":"This addresses definition freshness independently of OS feature updates."},{"text":"Change Windows 11 target release immediately","why":"A feature update is a different operation."},{"text":"Disable antivirus during incident","why":"This increases risk during an outbreak."}],"answer":0},{"prompt":"Verification","choices":[{"text":"Confirm OS build and AV signature versions separately","why":"Each operation has distinct success telemetry."},{"text":"Check only update ring name","why":"Policy naming does not prove installation."},{"text":"Check only that the machine restarted","why":"A reboot does not prove the intended updates."}],"answer":0}],"incident":{"prompt":"Why does the OS upgrade remain blocked?","choices":[{"text":"Hardware readiness or safeguard/compatibility hold","why":"Feature update readiness depends on system conditions and policy targeting."},{"text":"Defender definitions were updated yesterday","why":"Unrelated to Windows 11 hardware compatibility."},{"text":"User changed Teams theme","why":"Not an OS upgrade prerequisite."}],"answer":0},"concept":{"prompt":"Why monitor OS and antivirus updates separately?","choices":[{"text":"They change different components and produce different results","why":"Version evidence is needed for both endpoints."},{"text":"Both are the same update class","why":"They are separate servicing workflows."},{"text":"Neither needs internet access","why":"Servicing typically depends on distribution connectivity."}],"answer":0},"domain":"management","doc":"https://learn.microsoft.com/en-us/search/?terms=Windows%2011%20upgrades%20and%20Defender%20intelligence%20actions%20Microsoft%20Intune"},{"id":"A03","objectives":["APP-065","APP-067"],"title":"Microsoft 365 Apps policy and servicing channels","scenario":"Northstar supports Word, Excel and Outlook. The business needs predictable Microsoft 365 Apps updates and a consistent policy on what Office macros may run.","mental":"Microsoft 365 Apps admin center and Intune can both contribute to Office management, but deployment, cloud policy and update channel must be planned and verified as separate functions.","why":"App installation alone does not prove policy application or channel compliance.","prerequisites":"Confirm Microsoft 365 Apps licenses, supported client versions, target groups, update channel and whether Intune or the Microsoft 365 Apps admin center is authoritative for each setting.","verify":"Apps appear installed, update channel/report matches the intended ring, and policy settings show expected behavior on an eligible test user.","failure":"Office installs but receives updates from a different channel than intended.","recovery":"Inspect assigned cloud policy, Office update configuration, installation XML/ODT configuration, device policy precedence and inventory.","risk":"Avoid competing Office update channel assignments or untested macro policy changes company-wide.","settings":[{"prompt":"Office management design","choices":[{"text":"Separate deployment, app policy and servicing channel controls","why":"Each Office workload has a distinct purpose and reporting surface."},{"text":"Only install Word and assume all settings apply","why":"Installation says nothing about policy effect."},{"text":"Force all users to manage Office locally","why":"Defeats centralized governance."}],"answer":0},{"prompt":"Update rollout","choices":[{"text":"Pilot a supported Microsoft 365 Apps servicing channel","why":"Staged updates reveal add-in and workflow incompatibilities early."},{"text":"Change every device to a new channel without testing","why":"Unverified broad rollouts can impact critical add-ins."},{"text":"Remove Office license assignments","why":"Licensing removal does not solve channel selection."}],"answer":0},{"prompt":"Validation","choices":[{"text":"Check app version, effective channel and targeted policy status","why":"Installation, update state and policy have separate evidence."},{"text":"Only check a desktop shortcut","why":"Shortcut cannot confirm channel or macro policy."},{"text":"Only count active users","why":"User count does not prove device-side Office configuration."}],"answer":0}],"incident":{"prompt":"Office update channel does not match; what inspect?","choices":[{"text":"Competing update configurations and assigned servicing policy","why":"Policy precedence and installation configuration can affect the effective channel."},{"text":"Device background color","why":"Not relevant."},{"text":"Printer toner level","why":"Not relevant."}],"answer":0},"concept":{"prompt":"Why separate app deployment from Office cloud policy?","choices":[{"text":"Installation and application behavior are distinct operations","why":"You need different controls to install the app and govern how it operates."},{"text":"Both are just display names","why":"They have different effects."},{"text":"App policies only exist for Android","why":"Microsoft 365 apps have separate desktop policy controls."}],"answer":0},"domain":"applications","doc":"https://learn.microsoft.com/en-us/search/?terms=Microsoft%20365%20Apps%20policy%20and%20servicing%20channels%20Microsoft%20Intune"}];